steps.script:
$ErrorActionPreference='Stop'
$o=@{state='pending'}
try{
 $task=Get-ScheduledTask -TaskName 'TTiTTulares Local' -ErrorAction Stop
 if($task.State -eq 'Running'){$o.state='already_running'}
 else{Start-ScheduledTask -TaskName 'TTiTTulares Local' -ErrorAction Stop;$o.state='started'}
}catch{$o.state='error';$o.reason=[string]$_.Exception.Message}
Write-Output ('TTRESULT:'+($o|ConvertTo-Json -Compress))
